let file_inputs = document.querySelectorAll(".file_input");

function addFileName(){
for(var i = 0; i < file_inputs.length; i++){
file_inputs[i].onchange = function(e){
e.target.parentNode.childNodes[7].textContent = e.target.files[0].name;

}
}
}

addFileName();

function validateFields(){
document.querySelector("#single_product_form > div.errorContainer").innerHTML = '';
let errors = [];
if(!(document.querySelector("#contactChoice1").checked || (document.querySelector("#contactChoice2").checked))){;
errors.push('Nie wybrano płci');
}
if(document.querySelector("#contactChoice1").checked){
if(!(document.querySelector("#contactChoice15").checked || (document.querySelector("#contactChoice16").checked))){
errors.push('Czy jesteś w ciąży? lub czy podejrzewasz że jesteś w ciąży?');
}
if(!(document.querySelector("#contactChoice17").checked || (document.querySelector("#contactChoice18").checked))){
errors.push('Czy karmisz piersią?');
}
}

if(!(document.querySelector("#contactChoice3").checked || (document.querySelector("#contactChoice4").checked))){
errors.push('Czy masz myśli samobójcze lub choroby psychiczne?');

}
if(!(document.querySelector("#contactChoice5").checked || (document.querySelector("#contactChoice6").checked))){
errors.push('Czy występują u Ciebie uczulenia na leki?');
}

if(!(document.querySelector("#contactChoice7").checked || (document.querySelector("#contactChoice8").checked))){
errors.push('Czy przyjmujesz obecnie jakiekolwiek leki/preparaty?');
}
if(document.querySelector("#contactChoice7").checked){
if(document.querySelector("#single_product_form > div:nth-child(6) > div > textarea").value == ''){
errors.push('Nie wymieniono wszystkie stosowane leki');
}
}
if(document.querySelector("#single_product #single_product_container select").value == 'Inny (wpisz jaki)'){
if(document.querySelector("#single_product_form > div:nth-child(10) > textarea").value == ''){
errors.push('Wpisz lek jaki potrzebujesz');
}
}

if(!(document.querySelector("#contactChoice9").checked || (document.querySelector("#contactChoice10").checked))){
errors.push('Czy zdiagnozowano u Ciebie choroby przewlekłe lub choroby towarzyszące?');
}
if(document.querySelector("#contactChoice9").checked){
if(document.querySelector("#single_product_form > div:nth-child(9) > div.userText2 > textarea").value == ''){
errors.push('Wymień wszystkie stosowane leki oraz częstotliwość przyjmowania ');
}
}

if(document.querySelector("#single_product_form > div:nth-child(10) > textarea").value == ''){
errors.push("Napisz co Ci dolega");
}

if(!(document.querySelector("#contactChoice11").checked || (document.querySelector("#contactChoice12").checked))){
errors.push('Czy posiadasz dokumentacje medyczną?');
}
if(document.querySelector("#contactChoice11").checked){
if(document.querySelector("#file-name1").textContent == 'Nie wybrano pliku'){
errors.push('Nie wybrano pliku');
}
}

if(!(document.querySelector("#contactChoice19").checked || (document.querySelector("#contactChoice20").checked || document.querySelector("#contactChoice21").checked))){;
    errors.push('Czy dodałeś naszą placówke medyczną do swojego konta IKP?');
    }



document.querySelector('.errorContainer');
for (var i = 0; i<errors.length; i++){
let p = document.createElement('p');
if(i == 0){
let title = document.createElement('p');
title.className = 'errorTitle';
if(errors.length > 1){
title.innerHTML = 'Nie udzelono odpowiedzi na pytania:'
}else{
title.innerHTML = 'Nie udzelono odpowiedzi na pytanie:'
}
document.querySelector('.errorContainer').appendChild(title);
}
p.innerHTML = `<p>${errors[i]}</p>`
document.querySelector('.errorContainer').appendChild(p);
}


if(errors.length == '0'){
document.querySelector("#single_product_form > div.errorContainer").innerHTML = '';
document.querySelector(".errorContainer").style.display = 'none';
return true;
}else return false;


}

document.querySelector("#form_add_to_cart_btn").onclick = function(e){
if(!validateFields()){
document.querySelector(".errorContainer").style.display = 'block';
e.preventDefault();
window.scrollTo(0,0);
}
}

document.querySelector("#form_show_ikp_modal").onclick = function(){
document.querySelector(".modal_ikp").classList.add("open");
}
document.querySelector("#close_modal_btn").onclick = function(){
    document.querySelector(".modal_ikp").classList.remove("open");
    }

    window.addEventListener('keydown', (e) => {
if(e.key === "Escape"){
    document.querySelector(".modal_ikp").classList.remove("open");
}
    });

    document.querySelector(".modal_ikp .modal_ikp_box").addEventListener('click', event => {
        event._isClickWithInModal = true;
    });
    document.querySelector(".modal_ikp").addEventListener('click', event => {
        if (event._isClickWithInModal) return;
        event.currentTarget.classList.remove('open');
    });